def _parse(d):
    """SVG path data into subpaths of `(x, y, in_handle, out_handle)` anchors.

    A handle is the offset from its own anchor to a Bezier control point, which
    is exactly what `dex.Anchor` wants — so a cubic's first control belongs to
    the anchor it leaves and its second to the anchor it arrives at.

    A tracer closes a loop by curving back onto the point it started from, which
    would leave a duplicate anchor sitting on the first one. That last anchor's
    in-handle is the closing segment's control, so it is moved onto the first
    anchor and the duplicate dropped.
    """
    tokens = _TOKENS.findall(d)
    subpaths, anchors = [], []
    (cx, cy) = (0.0, 0.0)
    (sx, sy) = (0.0, 0.0)
    cmd = None
    numbers = []

    def flush():
        """Close off the loop being built."""
        if len(anchors) < 2:
            return
        (x, y, hin, _hout) = anchors[-1]
        if abs(x - anchors[0][0]) < 1e-6 and abs(y - anchors[0][1]) < 1e-6:
            (fx, fy, _fin, fout) = anchors[0]
            anchors[0] = (fx, fy, hin, fout)
            anchors.pop()
        subpaths.append(list(anchors))

    for (op, num) in tokens:
        if not num:
            numbers = []
            cmd = op
            if op in "Zz":
                flush()
                anchors.clear()
                (cx, cy) = (sx, sy)
            continue
        numbers.append(float(num))

        # A command takes its arguments a fixed number at a time and repeats for
        # as long as the numbers keep coming: two cubics in a row are written
        # once, with twelve numbers after the one letter.
        if cmd in "Mm" and len(numbers) == 2:
            flush()
            anchors.clear()
            if cmd == "M":
                (cx, cy) = (numbers[0], numbers[1])
            else:
                (cx, cy) = (cx + numbers[0], cy + numbers[1])
            (sx, sy) = (cx, cy)
            anchors.append((cx, cy, None, None))
            # Further pairs after a moveto are an implicit lineto.
            cmd = "L" if cmd == "M" else "l"
            numbers = []
        elif cmd in "Ll" and len(numbers) == 2:
            if cmd == "L":
                (cx, cy) = (numbers[0], numbers[1])
            else:
                (cx, cy) = (cx + numbers[0], cy + numbers[1])
            anchors.append((cx, cy, None, None))
            numbers = []
        elif cmd in "Cc" and len(numbers) == 6:
            (x1, y1, x2, y2, x, y) = numbers
            if cmd == "c":
                (x1, y1) = (cx + x1, cy + y1)
                (x2, y2) = (cx + x2, cy + y2)
                (x, y) = (cx + x, cy + y)
            if anchors:
                (px, py, pin, _pout) = anchors[-1]
                anchors[-1] = (px, py, pin, (x1 - px, y1 - py))
            anchors.append((x, y, (x2 - x, y2 - y), None))
            (cx, cy) = (x, y)
            numbers = []

    flush()
    return subpaths


def _flat(anchors, steps=4):
    """A coarse point list for a loop — enough to ask what contains what."""
    points = []
    for i, (x, y, _hin, hout) in enumerate(anchors):
        (nx, ny, nin, _nout) = anchors[(i + 1) % len(anchors)]
        points.append((x, y))
        if hout is None and nin is None:
            continue
        (c1x, c1y) = (x + hout[0], y + hout[1]) if hout else (x, y)
        (c2x, c2y) = (nx + nin[0], ny + nin[1]) if nin else (nx, ny)
        for s in range(1, steps):
            t = s / steps
            u = 1.0 - t
            points.append((
                u * u * u * x + 3 * u * u * t * c1x + 3 * u * t * t * c2x + t * t * t * nx,
                u * u * u * y + 3 * u * u * t * c1y + 3 * u * t * t * c2y + t * t * t * ny,
            ))
    return points


def _inside(point, poly):
    """Ray casting: whether `point` is inside the closed polygon `poly`."""
    (px, py) = point
    inside = False
    (jx, jy) = poly[-1]
    for (ix, iy) in poly:
        if (iy > py) != (jy > py) and px < (jx - ix) * (py - iy) / (jy - iy) + ix:
            inside = not inside
        (jx, jy) = (ix, iy)
    return inside


def _depths(loops):
    """How many other loops each loop sits inside.

    Quadratic in the number of loops, but the bounding-box test in front of the
    ray cast throws almost every pair out on a comparison — and it is done once
    for the drawing, not once a frame.
    """
    flats = [_flat(loop) for loop in loops]
    boxes = [(min(p[0] for p in f), min(p[1] for p in f),
              max(p[0] for p in f), max(p[1] for p in f)) for f in flats]
    depths = []
    for i, f in enumerate(flats):
        (ax0, ay0, ax1, ay1) = boxes[i]
        depth = 0
        for j, g in enumerate(flats):
            if i == j:
                continue
            (bx0, by0, bx1, by1) = boxes[j]
            if ax0 < bx0 or ay0 < by0 or ax1 > bx1 or ay1 > by1:
                continue
            if _inside(f[0], g):
                depth += 1
        depths.append(depth)
    return depths


def _loops():
    """Every traced loop, with the colour its nesting depth gives it."""
    loops = []
    for line in TRACE.strip().splitlines():
        loops.extend(_parse(line))
    depths = _depths(loops)
    # Outermost first, so a hole is painted after the shape it is a hole in.
    order = sorted(range(len(loops)), key=lambda i: depths[i])
    return [(loops[i], INK if depths[i] % 2 == 0 else PAPER) for i in order]


def _vec(x, y):
    return dex.Vector.new(float(x), float(y))


class Dynabook:
    """The traced drawing, painted to fit whatever box it is given.

    The trace is parsed and sorted once — on the first frame rather than in
    `__init__`, so the cost lands where the drawing is actually wanted and a
    node that is never drawn never pays it.
    """

    def __init__(self):
        self._loops = None

    def draw(self, ctx):
        origin = ctx.constraints.pos
        avail = ctx.constraints.available()
        (w, h) = (avail.x, avail.y)
        if not (math.isfinite(w) and math.isfinite(h)) or w <= 0.0 or h <= 0.0:
            (w, h) = (ART_W, ART_H)
        s = min(w / ART_W, h / ART_H)
        dx = (w - ART_W * s) / 2.0
        dy = (h - ART_H * s) / 2.0

        # The box is the *drawing*, not the room it was given: an image does
        # not paint outside its own frame.
        box = dex.DrawConstraints(
            pos=dex.ScreenPos.new(origin.x + dx, origin.y + dy),
            x=dex.AxisConstraint.Exactly(ART_W * s),
            y=dex.AxisConstraint.Exactly(ART_H * s),
            wrap=None,
            should_clip=True,
        )

        # The card the drawing is on, so it reads the same on any background.
        ctx.draw_node(
            dex.Path.polygon(
                [_vec(0, 0), _vec(ART_W * s, 0),
                 _vec(ART_W * s, ART_H * s), _vec(0, ART_H * s)],
                dex.Color.rgb(*PAPER),
                dex.Stroke.none(),
            ),
            box,
        )

        if self._loops is None:
            self._loops = _loops()
        for (anchors, colour) in self._loops:
            built = []
            for (x, y, hin, hout) in anchors:
                a = dex.Anchor.corner(_vec(x * s, y * s))
                if hin is not None:
                    a.in_handle = _vec(hin[0] * s, hin[1] * s)
                if hout is not None:
                    a.out_handle = _vec(hout[0] * s, hout[1] * s)
                built.append(a)
            path = dex.Path.polygon([_vec(0, 0)], dex.Color.rgb(*colour), dex.Stroke.none())
            path.anchors = built
            path.closed = True
            ctx.draw_node(path, box)

        return dex.DrawResult.Complete(
            region=dex.ScreenRegion.from_min_size(origin, dex.Vector.new(w, h))
        )

    def type_name(self):
        return "The Dynabook"


def transform():
    """Kay's drawing of two children with their Dynabooks."""
    return Dynabook()
